var DATA = {"diag": "Thomson scattering", "measures": "Electron temperature profile", "spectrum": "-2,0.1|-1,0.6|0,1.0|1,0.6|2,0.1"};
console.log("Diagnostic: " + DATA.diag + " | Measures: " + DATA.measures);
// Thomson scattering: fit a Gaussian to the scattered spectrum; width -> Te
var pts = DATA.spectrum.split("|").map(function (s) {
  var p = s.split(",").map(function (v) { return parseFloat(v); });
  return { x: p[0], y: p[1] };
});
var sx = 0, sw = 0, mx = 0;
pts.forEach(function (p) { sx += p.x * p.y; sw += p.y; });
mx = sx / sw;
var variance = 0;
pts.forEach(function (p) { variance += p.y * (p.x - mx) * (p.x - mx); });
variance /= sw;
var sigma = Math.sqrt(variance);
// Te proportional to sigma^2 (simplified calibration: Te_keV = 8 * sigma^2)
var Te = 8 * sigma * sigma;
console.log("Spectrum points: " + pts.length + " | fitted sigma=" + sigma.toFixed(3));
console.log("Inferred electron temperature: Te = " + Te.toFixed(2) + " keV");
console.log("RESULT: temperature inferred from Thomson spectrum width.");

